from __future__ import annotations; import sys; from pathlib import Path; sys.path.insert(0, str(Path(__file__).resolve().parents[2])); SAMPLE_XML_1 = '<?xml version="1.0" encoding="utf-8"?>\n<testsuite name="shard-1" tests="2" failures="0" errors="0" time="1.5">\n    <testcase classname="test_mod1" name="test_one" time="0.5"/>\n    <testcase classname="test_mod1" name="test_two" time="1.0"/>\n</testsuite>\n'
class TestSharedJunitHelper:
    def test_parse_junit_root_handles_missing_and_corrupt(self, tmp_path: Path) -> None: from common.testing.coverage import junit; missing = tmp_path / 'missing.xml'; assert junit.parse_junit_root(missing) is None; corrupt = tmp_path / 'corrupt.xml'; corrupt.write_text('<invalid-xml>', encoding='utf-8'); assert junit.parse_junit_root(corrupt) is None; valid = tmp_path / 'valid.xml'; valid.write_text(SAMPLE_XML_1, encoding='utf-8'); root = junit.parse_junit_root(valid); assert root is not None; assert root.tag == 'testsuite'; _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); from common.testing.coverage import junit; _m1_f = _m1_tmp / 's.xml'; _m1_f.write_text(SAMPLE_XML_1, encoding='utf-8'); _m1_cases = junit.iter_testcases(_m1_f); assert len(_m1_cases) == 2; _m1_names = [_m1_case.attrib.get('name') for _m1_case in _m1_cases]; assert _m1_names == ['test_one', 'test_two']
